package com.bank.invariant.service;

import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicReference;
import java.util.logging.Logger;

// STRONG consistency: the hard invariant "balance >= 0" is enforced atomically.
public class BalanceLedger {
    private static final Logger log = Logger.getLogger(BalanceLedger.class.getName());
    private BigDecimal balance;
    public BalanceLedger(BigDecimal opening) { this.balance = opening; }

    // Atomic + guarded: mirrors "UPDATE ... WHERE balance >= amt" under a row lock.
    public synchronized boolean withdraw(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) {           // invariant check INSIDE the atomic op
            log.warning(() -> "Rejected withdraw " + amount + " (would go negative), balance=" + balance);
            return false;
        }
        balance = balance.subtract(amount);
        log.info(() -> "Withdrew " + amount + ", balance=" + balance);
        return true;
    }
    public synchronized BigDecimal getBalance() { return balance; }
}
