package com.bank.invariant.service;

import java.util.*;
import java.util.logging.Logger;

// EVENTUAL consistency: no hard invariant; may lag, always available.
public class ActivityFeed {
    private static final Logger log = Logger.getLogger(ActivityFeed.class.getName());
    private final List<String> events = Collections.synchronizedList(new ArrayList<>());

    public void append(String event) {
        // In reality this is an async event to an AP store; staleness is acceptable.
        new Thread(() -> events.add(event)).start();   // propagated eventually
    }
    public List<String> snapshot() {
        log.info("Feed snapshot may be slightly stale (eventual consistency) — that's fine");
        synchronized (events) { return new ArrayList<>(events); }
    }
}
