package com.bank.invariant;

import com.bank.invariant.service.ActivityFeed;
import com.bank.invariant.service.BalanceLedger;
import java.math.BigDecimal;
import java.util.concurrent.*;

public class InvariantApplication {
    public static void main(String[] args) throws InterruptedException {
        BalanceLedger ledger = new BalanceLedger(new BigDecimal("100000"));
        ActivityFeed feed = new ActivityFeed();

        // 10 concurrent withdrawals of 20000 against 100000 — only 5 can succeed.
        ExecutorService pool = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 10; i++) {
            pool.submit(() -> {
                if (ledger.withdraw(new BigDecimal("20000"))) {
                    feed.append("Withdrawal Rs.20000"); // eventual, non-critical
                }
            });
        }
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        System.out.println("Final balance (must be >= 0): " + ledger.getBalance());
        Thread.sleep(100); // let eventual feed catch up
        System.out.println("Feed events (may lag): " + feed.snapshot().size());
    }
}
